<script setup lang="ts">
import BrandMark from '../components/BrandMark.vue';
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue';
import {createApiClient,ApiError} from '../api';
import {account, logout as signOut} from '../auth';
import {navigate} from '../navigation';
import type {AdminSummary,Observation,LogPage} from '../types';
const props=defineProps<{section:string}>();
const sections=[['overview','운영 현황','/admin'],['logs','로그 조회','/admin/logs'],['requests','API 요청','/admin/requests'],['llm','LLM 추론','/admin/llm'],['rag','증거 검색','/admin/rag'],['mcp','MCP 도구','/admin/mcp'],['errors','오류 분석','/admin/errors'],['system','시스템','/admin/system']];
const title=computed(()=>sections.find(s=>s[0]===props.section)?.[1]||'페이지 없음');
const admin=ref<typeof account.value>(null),authLoading=ref(true),error=ref(''),busy=ref(false),loading=ref(false);
const summary=ref<AdminSummary|null>(null),page=ref<LogPage|null>(null),updated=ref<number|null>(null),seconds=ref('3600'),component=ref(''),level=ref(''),query=ref(''),requestId=ref(''),traceId=ref(''),offset=ref(0),auto=ref(false),selected=ref<Observation|null>(null),dialog=ref<HTMLDialogElement|null>(null);
const api=createApiClient(()=>admin.value?.csrf);
let ctrl:AbortController|null=null,version=0,timer:ReturnType<typeof setInterval>|undefined;
const events:Record<string,string>={request_finished:'HTTP 응답',model_inference:'모델 추론',model_loaded:'모델 준비',mcp_call:'도구 호출',keyword_search:'키워드 검색',analysis_finished:'분석 종료'};
const outcomes:Record<string,string>={SUCCESS:'성공',ERROR:'실패',INVALID:'검증 실패',CANCELLED:'취소',BLOCKED:'차단'};
const time=(t:number|null)=>t===null?'—':new Date(t*1000).toLocaleString('ko-KR',{hour12:false});
const n=(v:number|null|undefined,d=0)=>v==null?'미측정':v.toLocaleString('ko-KR',{maximumFractionDigits:d});
const ms=(v:number|null|undefined)=>v==null?'미측정':`${n(v,1)} ms`;
const pct=(v:number|null|undefined)=>v==null?'데이터 없음':`${n(v*100,1)}%`;
const chartPoints=computed(()=>{const rows=summary.value?.buckets||[];const max=Math.max(1,...rows.map(b=>b.count));return rows.map((b,i)=>`${i*1000/23},${110-b.count/max*95}`).join(' ');});
const tiles=computed(()=>{if(!summary.value)return [];const m=summary.value.metrics;return [
 ['전체 HTTP 요청',n(m.http.count),'관측 표본'],['HTTP 성공률',pct(m.http.success_rate),'400 미만 / 전체 요청'],['HTTP 오류율',m.http.count?pct(m.http.errors/m.http.count):'데이터 없음','400 이상 응답 포함'],['평균 HTTP 지연',ms(m.http.average_ms),'응답 헤더까지'],['P95 HTTP 지연',ms(m.http.p95_ms),'실제 표본의 nearest rank'],['LLM 추론 시도',n(m.llm.count),`평균 ${ms(m.llm.average_ms)}`],['사건 증거 검색',n(m.rag.count),'keyword-bigram-v1'],['MCP 도구 호출',n(m.mcp.count),`실패 ${m.mcp.errors}건 포함`]];});
const facts=computed(()=>{const s=summary.value;if(!s)return [];const m=s.metrics.llm;
 if(props.section==='llm')return [['모델',s.model.model],['백엔드 / 리비전',`${s.model.backend} / ${s.model.revision}`],['어댑터',s.model.adapter_loaded?'적용 확인':'적용 안 됨'],['추론 시도 / 오류',`${m.count} / ${m.errors}`],['평균 / P50 / P95',`${ms(m.average_ms)} / ${ms(m.p50_ms)} / ${ms(m.p95_ms)}`],['입력 / 출력 토큰',`${n(m.input_tokens)} / ${n(m.output_tokens)}`],['과거 모델 변경 이력','수집 미설정']];
 if(props.section==='rag')return [['검색 방식','keyword-bigram-v1'],['범위','현재 권한·공개 버전의 사건 증거'],['평균 / P95',`${ms(s.metrics.rag.average_ms)} / ${ms(s.metrics.rag.p95_ms)}`],['참고 판례','BLOCKED · 권한 승인·검수 코퍼스 없음'],['벡터 / Hybrid / Rerank','미구현 / 미구현 / 미구현']];
 return [['준비 상태',s.ready?'ready=true':'ready=false'],['백엔드',s.model.backend],['모델 실행','기존 프로세스 잠금·단일 생성 유지'],['관측 시작',time(s.started)],['가장 오래된 보관 기록',time(s.oldest)],['보관 표본',`${s.retained} / 최대100,000개`],['CPU / 메모리','NOT_MEASURED / NOT_MEASURED'],['현재 OS 정답 격리 검사','NOT_RUN · 이 화면에서 검사하지 않음']];});
async function refresh(){
 if(!admin.value)return;ctrl?.abort();ctrl=new AbortController();const v=++version;loading.value=true;error.value='';
 const p=new URLSearchParams({seconds:seconds.value,component:component.value,level:level.value,q:query.value,request_id:requestId.value,trace_id:traceId.value,errors_only:String(props.section==='errors'),limit:'25',offset:String(offset.value)});
 try{const [s,l]=await Promise.all([api<AdminSummary>(`/api/admin/summary?seconds=${seconds.value}`,{signal:ctrl.signal}),api<LogPage>(`/api/admin/logs?${p}`,{signal:ctrl.signal})]);if(v!==version)return;summary.value=s;page.value=l;updated.value=Date.now()/1000;}
 catch(e){if(v!==version||e instanceof ApiError&&e.code==='CLIENT_CANCELLED')return;if(e instanceof ApiError&&['ADMIN_REQUIRED','AUTH_REQUIRED','CSRF_REQUIRED'].includes(e.code)){admin.value=null;summary.value=null;page.value=null;auto.value=false;}error.value=(e as Error).message;}
 finally{if(v===version)loading.value=false;}
}
function defaults(){component.value=({requests:'http',llm:'llm',rag:'rag',mcp:'mcp'} as Record<string,string>)[props.section]||'';level.value='';query.value='';requestId.value='';traceId.value='';offset.value=0;}
function apply(){offset.value=0;void refresh();}
function detail(row:Observation){selected.value=row;dialog.value?.showModal();}
function trace(row:Observation){component.value='';level.value='';query.value='';requestId.value=row.trace_id?'':row.request_id||'';traceId.value=row.trace_id||'';dialog.value?.close();apply();}
async function logout(){if(busy.value)return;busy.value=true;auto.value=false;try{await signOut();navigate('/login');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
watch(()=>props.section,()=>{defaults();void refresh();});
watch(auto,enabled=>{clearInterval(timer);if(enabled)timer=setInterval(()=>{if(!document.hidden&&!loading.value)void refresh();},10000);});
onMounted(async()=>{defaults();try{admin.value=await api('/api/admin/session');await refresh();}catch(e){if(e instanceof ApiError&&e.code!=='ADMIN_REQUIRED')error.value=e.message;}finally{authLoading.value=false;}});
onBeforeUnmount(()=>{version++;ctrl?.abort();clearInterval(timer);dialog.value?.close();});
</script>
<template><div class="admin-app">
<a class="skip" href="#admin-main">운영 본문으로 이동</a>
<aside class="admin-nav"><BrandMark compact /><span class="admin-brand-caption">운영자 콘솔</span><p class="nav-label">로컬 운영</p><nav aria-label="운영자 메뉴"><a v-for="s in sections" :key="s[0]" :href="s[2]" :aria-current="section===s[0]?'page':undefined"><span>{{s[1]}}</span><span aria-hidden="true">↗</span></a></nav><div class="nav-bottom">● 이 Mac 전용<a href="/cases">사용자 검토실로 ↗</a></div></aside>
<div class="admin-body"><header class="admin-top"><span>RE:CASE / {{title}}</span><div><span class="environment">LOCAL</span><span v-if="admin">{{admin.name}}</span><button v-if="admin" class="quiet" :disabled="busy" @click="logout">로그아웃</button><a v-else href="/cases">사용자 서비스 ↗</a></div></header>
<main id="admin-main">
<div v-if="authLoading" class="skeleton" role="status">운영자 세션을 확인하고 있습니다.</div>
<section v-else-if="!admin" class="admin-login"><h1>운영자 권한이 필요합니다.</h1><p>현재 계정으로는 운영 정보를 볼 수 없습니다.</p><a class="rc-button" href="/cases">사건 기록으로 돌아가기</a><p v-if="error" class="error" role="alert">{{error}}</p></section>
<template v-else>
<div class="page-heading"><div><p class="eyebrow">SERVICE OBSERVABILITY</p><h1>{{title}}</h1><p class="muted">로컬에서 수집한 실행 메타데이터입니다.</p></div><div class="heading-actions"><label class="period">조회 기간<select v-model="seconds" @change="apply"><option value="900">최근 15분</option><option value="3600">최근 1시간</option><option value="86400">최근 24시간</option><option value="604800">최근 7일</option></select></label><button class="secondary" :disabled="loading" @click="refresh">{{loading?'조회 중…':'새로고침'}}</button></div></div>
<p v-if="error" class="error" role="alert">{{error}} <button class="quiet" :disabled="loading" @click="refresh">다시 조회</button></p>
<div v-if="loading&&!summary" class="skeleton" role="status">운영 정보를 불러오고 있습니다.</div>
<template v-if="summary">
<div v-if="summary.model.backend==='fixture'" class="notice">모의 모델 테스트 서버입니다. 아래 호출은 실제 API/stdio MCP 기록이며 MLX 추론 성능을 뜻하지 않습니다.</div>
<div class="status-line"><span :class="['state',summary.ready?'ok':'bad']">● {{summary.ready?'서버 준비됨':'서버 준비되지 않음'}}</span><span>대기 {{summary.queue_size}} · 실행 {{summary.active_jobs}}</span><span>MCP {{summary.mcp_connected?'연결됨':'연결 확인 안 됨'}}</span><span class="updated">조회 {{time(updated)}}</span></div>
<p v-if="summary.dropped" class="error" role="alert">관측 기록 {{summary.dropped}}개가 저장되지 않았습니다. 이 프로세스의 집계가 불완전할 수 있습니다.</p>
<section v-if="section==='overview'" class="metrics" aria-label="관측 집계"><article v-for="t in tiles" :key="t[0]"><p>{{t[0]}}</p><strong>{{t[1]}}</strong><small>{{t[2]}}</small></article></section>
<section v-if="section==='overview'||section==='requests'" class="panel traffic"><div class="panel-heading"><h2>HTTP 요청 추이</h2><span class="muted">선택 기간 · 24구간 · {{summary.metrics.http.count}}건</span></div><svg v-if="summary.metrics.http.count" viewBox="0 0 1000 130" role="img" :aria-label="`HTTP 요청 ${summary.metrics.http.count}건의 시간 분포`" preserveAspectRatio="none"><path d="M0 110H1000 M0 60H1000 M0 10H1000" class="grid-lines"/><polyline :points="chartPoints" fill="none" class="traffic-line"/></svg><p v-else class="empty">수집된 요청이 없습니다.</p><div class="chart-caption"><span>{{time((updated||0)-Number(seconds))}}</span><span>현재</span></div></section>
<section v-if="['llm','rag','system'].includes(section)" class="panel technical"><div class="panel-heading"><h2>{{section==='llm'?'현재 로드 모델':section==='rag'?'공개 사건 증거 검색':'현재 프로세스'}}</h2><span class="state">{{section==='rag'?'KEYWORD':'LOCAL'}}</span></div><dl><template v-for="f in facts" :key="f[0]"><dt>{{f[0]}}</dt><dd>{{f[1]}}</dd></template></dl><p v-if="section==='llm'" class="muted">추론 벽시계 시간은 취소·실패를 포함합니다. 토큰을 받지 못한 호출은 토큰 합계에서 제외합니다. 출력 검증 실패는 오류 분석의 system 기록에서 확인합니다.</p><p v-else-if="section==='rag'" class="muted">검색 시간은 MCP 전달·대기 시간을 포함합니다. 검색어·원문은 저장하지 않습니다. 상세에서 증거 ID·점수·빈 결과를 확인하세요.</p><p v-else class="muted">과거 UID499 검사 결과를 현재 프로세스의 보안 검사로 표시하지 않습니다. OS 권한 변경·평가 정답 조회는 제공하지 않습니다.</p></section>
<section v-if="section==='mcp'" class="panel technical"><div class="panel-heading"><h2>recase-evidence</h2><span class="state">STDIO · {{summary.mcp_connected?'연결됨':'미연결'}}</span></div><ul class="tool-list"><li v-for="tool in summary.tools" :key="tool"><code>{{tool}}</code><span>{{tool==='search_reference_judgments'?'BLOCKED 반환':'권한 있는 공개 증거'}}<br>호출 {{summary.tool_metrics?.[tool]?.count??'미수집'}} · 성공 {{pct(summary.tool_metrics?.[tool]?.success_rate)}} · 평균 {{ms(summary.tool_metrics?.[tool]?.average_ms)}}</span></li></ul><p class="muted">도구별 집계는 선택 기간의 실제 호출을 기준으로 합니다. 개별 실패·지연은 아래 기록에서 확인하세요. 임의 도구 실행 기능은 없습니다.</p></section>
<section v-if="section==='errors'" class="panel"><div class="panel-heading"><h2>오류 유형</h2><span class="muted">실제 발생 수</span></div><p v-if="!summary.error_groups.length" class="empty">기록된 오류가 없습니다. 미관측 구간의 정상 여부는 판단할 수 없습니다.</p><ul v-else class="error-groups"><li v-for="g in summary.error_groups" :key="g.component+g.error"><button class="quiet" @click="component=g.component;query=g.error;apply()"><span>{{g.component}} / {{g.error}}</span><strong>{{g.count}}건</strong></button></li></ul></section>
<section class="panel logs" aria-label="실행 기록"><div class="panel-heading"><h2>{{section==='overview'?'최근 실행 기록':'실행 기록'}}</h2><label class="auto"><input type="checkbox" v-model="auto">10초마다 조회</label></div>
<form class="filters" @submit.prevent="apply"><label>컴포넌트<select v-model="component"><option value="">전체</option><option v-for="c in ['http','llm','rag','mcp','system']" :key="c">{{c}}</option></select></label><label>레벨<select v-model="level"><option value="">전체</option><option>INFO</option><option>WARN</option><option>ERROR</option></select></label><label class="query">이벤트·오류 검색<input v-model="query" maxlength="80" placeholder="이벤트, 코드, 경로"></label><label>Request ID<input v-model="requestId" maxlength="32" placeholder="요청 식별자"></label><label>Trace ID<input v-model="traceId" maxlength="20" placeholder="JOB-…"></label><button class="secondary" :disabled="loading">적용</button><button class="quiet" type="button" :disabled="loading" @click="defaults();refresh()">초기화</button></form>
<p v-if="component&&summary.metrics[component]" class="metric-note muted">{{component}} 전체 표본 {{summary.metrics[component].count}}건 · 평균 {{ms(summary.metrics[component].average_ms)}} · P95 {{ms(summary.metrics[component].p95_ms)}}. 필터는 아래 기록 표에 적용됩니다.</p><p v-if="loading" class="loading-note" role="status">기록을 불러오고 있습니다.</p>
<div v-if="page&&!page.items.length" class="empty"><h3>이 조건에 맞는 기록이 없습니다.</h3><p>기간·필터를 바꾸거나 사용자 검토실에서 분석한 뒤 다시 조회하세요.</p></div>
<div v-else class="table-scroll" tabindex="0" aria-label="실행 기록 표 가로 스크롤"><table><thead><tr><th>시각 / 레벨</th><th>컴포넌트 · 실행</th><th>결과</th><th>소요 시간</th><th>요청 / 분석 연결</th><th>상세</th></tr></thead><tbody><tr v-for="r in page?.items" :key="r.id"><td><time>{{time(r.created)}}</time><small :class="r.level.toLowerCase()">{{r.level}}</small></td><td><span class="component">{{r.component}}</span><strong>{{events[r.event]||r.event}}</strong><code>{{r.operation||r.route||r.event}}</code></td><td><span :class="['outcome',r.outcome==='SUCCESS'?'ok':'bad']">{{r.status||outcomes[r.outcome]}}</span><small v-if="r.error">{{r.error}}</small><small v-if="r.component==='rag'">{{r.hit_count===null?'검색 실패':r.hit_count+'개 문서'}}</small><small v-if="r.component==='llm'">입력 {{n(r.input_tokens)}} · 출력 {{n(r.output_tokens)}}</small></td><td class="numeric">{{ms(r.duration_ms)}}</td><td><button v-if="r.request_id||r.trace_id" class="id-button" :title="r.trace_id||r.request_id||''" @click="trace(r)">{{r.trace_id||r.request_id?.slice(0,12)}} ↗</button><span v-else class="muted">연결 정보 없음</span></td><td><button class="quiet" @click="detail(r)" :aria-label="`${r.id}번 기록 상세`">상세</button></td></tr></tbody></table></div>
<div class="pagination"><span>{{page?.total||0}}건 · {{page?.items.length?offset+1:0}}–{{offset+(page?.items.length||0)}}</span><div><button class="quiet" :disabled="loading||offset===0" @click="offset=Math.max(0,offset-25);refresh()">이전</button><button class="quiet" :disabled="loading||offset+25>=(page?.total||0)" @click="offset+=25;refresh()">다음</button></div></div></section>
<p class="scope-note">관측 시작 이후 보관 중인 기록만 집계합니다. HTTP에는 관리자·상태 조회·정적 자산이 포함됩니다. SSE 지연은 헤더까지이며 스트림 전체 수명이 아닙니다. 원문·프롬프트·비밀키·정답은 저장하지 않습니다.</p>
</template></template>
</main><footer>RE:CASE OPERATIONS · LOCAL SYNTHETIC SERVICE</footer></div>
<dialog ref="dialog" class="detail-dialog" aria-label="실행 기록 상세"><template v-if="selected"><div class="panel-heading"><h2>{{events[selected.event]||selected.event}}</h2><button class="quiet" @click="dialog?.close()" aria-label="기록 상세 닫기">닫기</button></div><dl><dt>시각</dt><dd>{{time(selected.created)}}</dd><dt>컴포넌트 / 결과</dt><dd>{{selected.component}} / {{outcomes[selected.outcome]}}</dd><dt>실행</dt><dd>{{selected.operation||selected.route}}</dd><dt>지연</dt><dd>{{ms(selected.duration_ms)}}</dd><dt>Request ID</dt><dd>{{selected.request_id||'수집되지 않음'}}</dd><dt>Trace ID</dt><dd>{{selected.trace_id||'해당 없음'}}</dd><dt>오류 코드</dt><dd>{{selected.error||'없음'}}</dd><template v-if="selected.component==='llm'"><dt>입력 / 출력 토큰</dt><dd>{{n(selected.input_tokens)}} / {{n(selected.output_tokens)}}</dd></template><template v-if="selected.component==='rag'"><dt>검색 문서</dt><dd>{{selected.hit_count===null?'검색 실패':selected.hit_count+'개'}}<ul><li v-for="d in selected.documents" :key="d.id"><code>{{d.id}}</code> · 점수 {{d.score}}</li></ul></dd></template></dl><button v-if="selected.trace_id||selected.request_id" class="secondary" @click="trace(selected)">이 요청·분석의 기록 보기</button><p class="muted">원문과 예외 메시지·스택은 저장하지 않습니다.</p></template></dialog>
</div></template>
<style scoped src="../admin.css"></style>
